        timeContext = productionContext(local.hour, local.minute),
        budget = snapshot.budget,
    )
    return BudgetProbe(
        remaining = GetCurrentBudgetStatus.statusAt(schedule, snapshot.budget, minuteOfDay).remainingPoints,
        deliverable = delivered.size,
    )
